document.querySelector('.menu-toggle')?.addEventListener('click',function(){const nav=document.querySelector('nav');const open=nav.classList.toggle('open');this.setAttribute('aria-expanded',String(open));this.textContent=open?'Cerrar':'Menú';});
document.querySelector('[data-print]')?.addEventListener('click',()=>window.print());
document.querySelector('#brief')?.addEventListener('submit',e=>{e.preventDefault();const d=new FormData(e.target);const body=`Hola Álvaro,\n\nSoy ${d.get('nombre')} de ${d.get('empresa')||'un proyecto independiente'}.\nTipo de propuesta: ${d.get('tipo')}\n\n${d.get('mensaje')}\n\nContacto: ${d.get('email')}`;window.location.href='mailto:alvarolinarescontacto@gmail.com?subject='+encodeURIComponent('Propuesta: '+d.get('tipo'))+'&body='+encodeURIComponent(body);document.querySelector('#form-status').textContent='Se ha solicitado abrir tu aplicación de correo con el borrador. Revisa el mensaje y pulsa enviar allí. Si no se abre, escribe a alvarolinarescontacto@gmail.com.';});
